import type { ItemModel } from './model.js';
import { createHash } from 'node:crypto';

export interface DecisionArchetype {
  id: string;
  action: string;
  domains: string[];
  /** Author-specified work units: cost, delay, residual exposure. */
  workUnits: [number, number, number];
  preservesScope: boolean;
  reversible: boolean;
}
export interface DecisionArchetypeCatalog {
  progression: { Junior: string; Middle: string; Senior: string };
  actions: DecisionArchetype[];
  bundles: Record<string, string[]>;
}
type Action = [string, string, number, number, number];
function catalog(
  progression: [string, string, string],
  actions: Action[],
  bundles: Record<string, string[]>,
): DecisionArchetypeCatalog {
  return {
    progression: { Junior: progression[0], Middle: progression[1], Senior: progression[2] },
    actions: actions.map(([id, action, cost, delay, exposure]) => ({
      id,
      action,
      workUnits: [cost, delay, exposure],
      domains: Object.entries(bundles)
        .filter(([, ids]) => ids.includes(id))
        .map(([domain]) => domain),
      preservesScope: true,
      reversible: true,
    })),
    bundles,
  };
}

