export function modelDecisionCatalog(model: ItemModel): DecisionArchetype[] {
  const catalog = decisionCatalogs[model.specialization];
  const ids = model.decisionArchetypes || catalog?.bundles[model.competencyDomain || ''];
  if (!catalog || !ids || ids.length < 4)
    throw new Error(`Нет предметного decision catalog: ${model.id}`);
  return ids.map((id) => {
    const action = catalog.actions.find((entry) => entry.id === id);
    if (!action || !action.domains.includes(model.competencyDomain!))
      throw new Error(`${model.id}: archetype ${id} не поддерживает область`);
    return structuredClone(action);
  });
}

/** Candidate form tokens preserve action identity without exposing internal catalog IDs. */
export function actionToken(action: DecisionArchetype): string {
  return `choice-${createHash('sha256').update(action.action).digest('hex').slice(0, 16)}`;
}

